    def _process_frame(self, csi_raw):
        if csi_raw is None:
            return None
        # Pass 25: capture the PRISTINE complex CSI before any blend/normalisation so the
        # range matched-filter sees the true delay phase (ground-truth return in sim, or
        # genuine instrument capture in live mode). Only accept a capture that actually
        # carries phase — a magnitude-only frame (phstd≈0) would wipe the delay info.
        try:
            _cap = np.atleast_1d(csi_raw).ravel()[:DEFAULT_SUBCARRIERS].astype(np.complex64).copy()
            # Pass 35 (T-ESPCSI): phase sanitization (unwrap + linear detrend + Hampel)
            if getattr(self, "_phase_sanitize", False):
                try:
                    _cap = self.phase_sanitizer.sanitize(_cap)
                    self.psych_profile["phase_sanitized"] = True
                except Exception:
                    pass
            if np.std(np.angle(_cap)) > 1e-3:
                self._last_raw_csi = _cap
            elif getattr(self, "_last_raw_csi", None) is None:
                self._last_raw_csi = _cap   # bootstrap even if phase-less
            # Pass 31 (T1): accumulate mean CSI phase for the wireless-BCI window.
            if hasattr(self, "_bci_phase_hist"):
                self._bci_phase_hist.append(float(np.mean(np.angle(_cap))))
            # Pass 32 (T2): accumulate slow-time complex CSI for the radar SAR history.
            if hasattr(self, "_radar_csi_hist"):
                self._radar_csi_hist.append(_cap.copy())
            # Pass 35 (T-MVS): EspectreMVS motion detector on the sanitized CSI amplitude
            if hasattr(self, "mvs_detector"):
                try:
                    _mvs = self.mvs_detector.process(_cap)
                    self.psych_profile["mvs_state"]      = _mvs["state"]
                    self.psych_profile["mvs_confidence"] = _mvs["confidence"]
                    self.psych_profile["mvs_variance"]   = _mvs["variance"]
                except Exception as _mve:
                    log.debug(f"[MVS] {_mve}")
        except Exception:
            self._last_raw_csi = None

        # Pass 18: blend real router CSI with incoming signal for maximum sensitivity.
        # RouterCSICapture tries Nexmon UDP → /proc/net/wireless → ioctl → iw → RSSI-synth.
        # Blend weight: 0.35 real + 0.65 sim/udp so the existing pipeline is not disrupted.
        try:
            real_csi = self.router_csi.capture()   # shape (DEFAULT_SUBCARRIERS,) complex64
            # Pass 25: when a real capture method is active (Nexmon/proc/iw) blend it in for
            # genuine sensing. In pure SIMULATION the incoming csi_raw is the GROUND-TRUTH
            # scene return — blending the router's RSSI-synth (its own phantom target) would
            # corrupt the clean delay phase the matched filter needs, so we keep sim CSI pure.
            _real_active = (hasattr(self.router_csi, "is_real_capture")
                            and self.router_csi.is_real_capture())
            if _real_active:
                csi_flat = np.atleast_1d(csi_raw).ravel()
                n = min(len(csi_flat), len(real_csi), DEFAULT_SUBCARRIERS)
                csi_raw_arr = np.array(csi_flat[:n], dtype=np.complex64)
                blend = 0.65 * csi_raw_arr + 0.35 * real_csi[:n]
                if hasattr(csi_raw, 'shape') and csi_raw.ndim > 1:
                    csi_raw = np.resize(blend, csi_raw.shape)
                else:
                    csi_raw = blend
        except Exception:
            pass  # never break the pipeline

        # Pass 18: produce real imagery from current CSI + voxel grid
        try:
            self._last_render = self.img_renderer.render(
                np.atleast_1d(csi_raw).ravel()[:DEFAULT_SUBCARRIERS],
                self.voxel_grid)
        except Exception:
            pass

        # List 1.4: feed calibrator
        self.calibrator.feed(np.abs(csi_raw).ravel()[:DEFAULT_SUBCARRIERS])

        # List 1.11: agents run sequentially per frame.
        # (Previously a multiprocessing.Pool was created AND destroyed every frame at
        #  ~100 Hz — the per-frame process spawn/teardown cost far exceeds the light
        #  per-agent numpy work and pickles the whole fuser each call, which exhausted
        #  memory on long runs. Sequential is faster and stable for this workload.)
        results = [self._agent_process(i, csi_raw) for i in range(NUM_AGENTS)]

        self._fuse_agents(results)

        with self.history_lock:
            # Pass 21: store per-subcarrier amplitude vector (shape DEFAULT_SUBCARRIERS,)
            # so _update_plot receives a proper 2D waterfall array.
            amp_snap = np.abs(np.atleast_1d(csi_raw).ravel()[:DEFAULT_SUBCARRIERS]).astype(np.float32)
            if len(amp_snap) < DEFAULT_SUBCARRIERS:
                amp_snap = np.pad(amp_snap, (0, DEFAULT_SUBCARRIERS - len(amp_snap)))
            self.history.append(amp_snap)
            # List 1.7: separate 2.4 / 5 GHz band histories
            self.history_24ghz.append(amp_snap.copy())
            self.history_5ghz.append(amp_snap.copy())

        # List 1.9: optional recording
        if self.recorder:
            self.recorder.record(csi_raw, self.psych_profile)

        presence = float(np.max(self.voxel_grid)) > 0.25
        return {
            'presence': presence,
            'blood_flow': float(np.mean(self.voxel_grid[VOXEL_RES//4:3*VOXEL_RES//4])) > 0.2,
            'psych_profile': self.psych_profile.copy()
        }

    def _simulation_mode(self):
        mode_label = "DEMO-ONLY (no real RF)" if self.demo_only else "SIMULATION"
        log.info(f"[SIM] {mode_label}: BCI + vitals + psychology (humanitarian life-saving mode)")
        log.info("[ADAPT] Running 8s zero-shot domain-calibration dance …")  # List 2.12
        t = 0
        hop_freqs = [1.0, 2.0, 6.0]            # List 2.3: 2.4GHz channels / 5GHz
        last_report = time.time()
        adapt_start = time.time()
        # List 3.12: optional webcam ground-truth validation (never stores video)
        wv = webcam_validate()
        self.psych_profile["webcam_validation"] = wv
        if wv is not None:
            log.info(f"[WEBCAM] Silhouette validation metric: {wv:.3f}")
        # HITCH: seed simulated ambient APs ONLY in sim-validate test mode. In default
        # REAL-DATA mode we register no fake APs — only genuinely-scanned ones appear.
        if self.sim_validate:
            for i in range(5):
                self.network_locator.register_ap(
                    f"sim-ap-{i}", lat=37.0 + i * 0.01, lon=-122.0 - i * 0.01,
                    ssid=f"NEPA-SIM-{i}", rssi=-55 - i * 6)
        else:
            # Real mode: trigger an immediate genuine AP scan so the map populates fast.
            try:
                self.network_locator._last_wifi_scan = 0.0  # force scan now
                self.network_locator.scan_wifi_live()
            except Exception:
                pass
        # Pass 21+22: pre-compute stable RNG + subcarrier grid for simulation
        _rng_sim = np.random.default_rng(seed=42)
        _sc = np.linspace(0, 2 * np.pi, DEFAULT_SUBCARRIERS)  # subcarrier phase ramp
        df = 20e6 / DEFAULT_SUBCARRIERS
        k = np.arange(DEFAULT_SUBCARRIERS, dtype=np.float64) - DEFAULT_SUBCARRIERS // 2
        while self.running:
            # List 2.3: dynamic frequency hopping every 50ms (rotate channel)
            self.hop_channel = int((t * SAMPLING_RATE) // 5) % len(hop_freqs)
            ch = hop_freqs[self.hop_channel]

            # ── Pass 26: REAL-DATA-FIRST CSI SOURCE ──────────────────────────────
            # DEFAULT: capture genuine CSI/RSSI from the connected router every frame
            # (Nexmon → SDR → /proc/net/wireless → ioctl → iw → multi-AP ARP synthesis).
            # The display then shows ONLY real, measured data — nothing fabricated.
            # --sim-validate: drive CSI from the synthetic GroundTruthScene so the
            # reconstruction can be graded against known truth (offline test only).
            self._sim_t = t
            if self.sim_validate:
                illum = self._rf_illuminators[self._rf_idx % len(self._rf_illuminators)]
                self._rf_idx += 1
                csi_row = self.gt_scene.synthesize_csi(t, illuminator=illum)
                self.psych_profile["rf_illuminator"] = illum
                self.psych_profile["rf_band_hz"] = RF_ILLUMINATORS[illum]["f_hz"]
                csi = csi_row.reshape(1, DEFAULT_SUBCARRIERS).astype(np.complex64)
            else:
                # REAL capture — pull the live router/instrument CSI this frame.
                real_csi = self.router_csi.capture()  # (DEFAULT_SUBCARRIERS,) complex64
                self.psych_profile["rf_illuminator"] = self.router_csi.method
                csi = np.asarray(real_csi, dtype=np.complex64).reshape(1, DEFAULT_SUBCARRIERS)
            result = self._process_frame(csi)

            # Pass 28: periodic wideband high-GHz spectrum survey. Real SDR sweep when
            # hardware is present; otherwise a [ESTIMATED] band table. Runs on a slow
            # cadence so it never stalls the live display loop.
            _fc = int(t * SAMPLING_RATE)
            if _fc - self._spectrum_last_frame >= self._spectrum_interval:
                self._spectrum_last_frame = _fc
                try:
                    _survey = self.spectrum.sweep()
                    _real_bands = [n for n, e in _survey.items() if e.get("real")]
                    self.psych_profile["spectrum_survey"] = _survey
                    self.psych_profile["spectrum_real_bands"] = _real_bands
                    self.psych_profile["spectrum_band_count"] = len(_real_bands)
                    # T0-7: accumulate waterfall row for the signal-tab waterfall
                    wf_row = []
                    for _bn, _bd in _survey.items():
                        if isinstance(_bd, dict):
                            _pk = _bd.get("peak_power_dbm") if _bd.get("real") else None
                            wf_row.append(float(_pk) if _pk is not None else -120.0)
                        else:
                            wf_row.append(-120.0)
                    if wf_row:
                        self._spectrum_wf_history.append(wf_row)
                except Exception as _e:
                    log.debug(f"[Spectrum] sweep skipped: {_e}")

            # AP refresh: sim-validate re-seeds phantom APs; REAL mode rescans genuine APs.
            if int(t * SAMPLING_RATE) % 500 == 0:
                if self.sim_validate:
                    for i in range(5):
                        self.network_locator.register_ap(
                            f"sim-ap-{i}", lat=37.0 + i * 0.01, lon=-122.0 - i * 0.01,
                            ssid=f"NEPA-SIM-{i}", rssi=-55 - i * 6)
                else:
                    try:
                        self.network_locator.scan_wifi_live()  # throttled internally
                    except Exception:
                        pass

            # List 2.12: mark domain adaptation complete after 8s dance
            if not self.domain_adapted and time.time() - adapt_start >= 8:
                self.domain_adapted = True
                log.info("[ADAPT] Zero-shot domain adaptation complete — room signature learned.")

            if result:
                p = result['psych_profile']
                cal = "✓" if self.calibrator.calibrated else f"{self.calibrator.progress*100:.0f}%"
                alerts = ("  ⚠ " + ",".join(p['anomaly_alerts'])) if p['anomaly_alerts'] else ""
                # Pass 26: real-data status (default) vs accuracy gauge (sim-validate)
                if self.sim_validate:
                    _stat = (f"ACC={p.get('recon_accuracy',0):.0f}%"
                             f"{'✓' if p.get('recon_locked') else ''} RF={p.get('rf_illuminator','?')}")
                else:
                    _live = "LIVE" if p.get("real_capture") else "synth"
                    _stat = (f"REAL[{_live}]={p.get('capture_method','?')} "
                             f"nodes={p.get('real_node_count',0)}"
                             f"(LAN{p.get('lan_host_count',0)}/AP{p.get('ap_count',0)}) "
                             f"instr={p.get('instrument_count',0)} fixes={p.get('multilat_fix_count',0)} "
                             f"RSSI={p.get('live_rssi_dbm',-70):.0f}dBm SNR={p.get('live_snr_db',0):.0f}dB")
                log.info(
                    f"[{p['person_id']} x{p['num_persons']}] BCI={p['bci_state']:9s} | "
                    f"HR={p['heart_rate_bpm']:5.1f} BR={p['breath_rate_bpm']:4.1f} | "
                    f"Threat={'HIGH' if p['threat_level']>0.5 else 'LOW '} | "
                    f"{_stat} | "
                    f"ch{self.hop_channel} SigQ={p['signal_quality']:.2f} Cal={cal}{alerts}")

                # List 2.9: auto-export clinical report every 60s.
                # Fixed rolling filename so a 24/7 run overwrites one file instead of
                # accumulating ~1440 timestamped reports per day.
                if time.time() - last_report >= 60:
                    export_clinical_report(p, result, path="nepa_report_latest.md")
                    last_report = time.time()

                # List 3.9 / Pass 24: TTS diagnostic readout every 15s (hands-free).
                # Critical life-safety alerts (FALL/RESPIRATORY_ARREST) are announced
                # immediately and prioritised over routine readouts.
                _alerts = p.get('anomaly_alerts', [])
                _critical = [a for a in _alerts if any(k in a for k in
                             ("FALL_DETECTED", "RESPIRATORY_ARREST", "PROXIMITY_ALERT"))]
                # Immediate critical announcement (independent of 15s cadence)
                if _critical and time.time() - getattr(self, "_last_critical_tts", 0) >= 5:
                    self.tts.say(f"Warning. {_critical[0].replace('_', ' ')} detected.")
                    self._last_critical_tts = time.time()
                if time.time() - self._last_tts >= 15:
                    _np = int(p.get('num_persons', 1))
                    _pr = p.get('person_ranges', [])
                    _rng_txt = (f"{_np} person{'s' if _np != 1 else ''} detected. "
                                if _np >= 1 else "")
                    _alert_txt = ('Alert: ' + (_critical[0] if _critical else _alerts[0]).replace('_', ' ')
                                  if _alerts else 'No anomalies.')
                    self.tts.say(f"{_rng_txt}State {p['hmm_state']}, heart rate "
                                 f"{p['heart_rate_bpm']:.0f}, mind score "
                                 f"{p['overall_mind_reading_score']:.0f} of 100. "
                                 f"{_alert_txt}")
                    self._last_tts = time.time()
            t += 1 / SAMPLING_RATE
            time.sleep(0.008)

    def _udp_listener(self):
        # List 1.12: demo-only forbids real RF capture
        if self.demo_only:
            log.warning("[UDP] --demo-only active; refusing real RF capture. Use sim mode.")
            return self._simulation_mode()
        retry_delay = 2
        while self.running:
            sock = None
            try:
                sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
                sock.settimeout(5.0)
                sock.bind(('', self.udp_port))
                log.info(f"[UDP] Listener active on port {self.udp_port}")
                while self.running:
                    try:
                        data, addr = sock.recvfrom(BUFFER_SIZE)
                        csi = self._parse_csi(data)
                        if csi is not None:
                            # List 1.6: parse RSSI if present, update distance
                            if len(data) >= 8:
                                try:
                                    rssi = struct.unpack('<h', data[4:6])[0] / 10.0
                                    self.last_rssi = float(np.clip(rssi, -100, 0))
                                    self.estimated_distance_m = rssi_distance(self.last_rssi)
                                except Exception:
                                    pass
                            self._process_frame(csi)
                    except socket.timeout:
                        continue
            except OSError as e:
                log.warning(f"[UDP] Socket error: {e}; reconnecting in {retry_delay}s")
                time.sleep(retry_delay)
            finally:
                if sock is not None:
                    try:
                        sock.close()
                    except Exception:
                        pass

    def _update_plot(self, frame):
        # Pass 23: pause support — skip render when paused
        if getattr(self, "_paused", False):
            return
        # Pass 27: never leave panels blank-white. Before data exists (calibration),
        # paint every axis dark with an INITIALIZING message instead of returning.
        if len(self.history) < 2:
            for _ax in [self.ax2d, self.ax_doppler, self.ax_heatmap, self.ax_vitals,
                        self.ax_bci, self.ax_diag, self.ax_img_amp, self.ax_img_holo,
                        self.ax_img_voxel, self.ax_img_comp]:
                try:
                    _ax.cla(); _ax.set_facecolor('#080808'); _ax.axis('off')
                except Exception:
                    pass
            try:
                self.ax3d.cla(); self.ax3d.set_facecolor('#080808')
            except Exception:
                pass
            try:
                self.ax_diag.text(0.5, 0.5,
                    "N.E.P.A. — INITIALIZING REAL-DATA CAPTURE ...\n"
                    "scanning router / ARP hosts / APs",
                    ha='center', va='center', color='#00ffcc', fontsize=12,
                    family='monospace', transform=self.ax_diag.transAxes)
            except Exception:
                pass
            return
        # Pass 21: history stores float32 per-subcarrier amplitude rows
        with self.history_lock:
            hist_list = list(self.history)
        amp_hist = np.abs(np.array(hist_list, dtype=np.float32))   # shape (T, DEFAULT_SUBCARRIERS)
        p = self.psych_profile

        # ── Panel 1: CSI waterfall (time × subcarrier amplitude) ─────────────
        self.ax2d.cla()
        self.ax2d.set_facecolor('#080808')
        if amp_hist.ndim == 2 and amp_hist.shape[1] > 1:
            disp = amp_hist[-min(120, len(amp_hist)):].T   # (64, T)
            vmin, vmax = float(disp.min()), float(disp.max())
            if vmax > vmin + 1e-6:
                self.ax2d.imshow(disp, aspect='auto', cmap='viridis', origin='lower',
                                 vmin=vmin, vmax=vmax, interpolation='nearest')
            else:
                self.ax2d.imshow(np.ones_like(disp) * 0.5, aspect='auto', cmap='viridis',
                                 origin='lower', interpolation='nearest')
        self.ax2d.set_title('CSI Waterfall (Amplitude × Time)', fontsize=9, color='cyan')
        self.ax2d.set_xlabel('Frame', fontsize=7, color='#aaa')
        self.ax2d.set_ylabel('Subcarrier', fontsize=7, color='#aaa')
        self.ax2d.tick_params(colors='#888', labelsize=6)

        # ── Panel 2: Micro-Doppler spectrogram ───────────────────────────────
        self.ax_doppler.cla()
        self.ax_doppler.set_facecolor('#080808')
        try:
            mean_amp = amp_hist.mean(axis=1).astype(np.float64)   # (T,)
            if len(mean_amp) >= 8:
                nperseg = min(32, len(mean_amp) // 2)
                f_arr, t_arr, Sxx = sig.spectrogram(mean_amp, fs=float(SAMPLING_RATE),
                                                     nperseg=nperseg, noverlap=nperseg // 2)
                Sxx_db = 10.0 * np.log10(Sxx + 1e-12)
                self.ax_doppler.pcolormesh(t_arr, f_arr, Sxx_db, shading='gouraud', cmap='plasma')
                self.ax_doppler.set_ylabel('Freq (Hz)', fontsize=7, color='#aaa')
                self.ax_doppler.set_xlabel('Time (s)', fontsize=7, color='#aaa')
        except Exception:
            self.ax_doppler.text(0.5, 0.5, 'Building…', ha='center', va='center',
                                  color='cyan', transform=self.ax_doppler.transAxes, fontsize=9)
        self.ax_doppler.set_title('Micro-Doppler (Body Motion Spectrogram)', fontsize=9, color='cyan')
        self.ax_doppler.tick_params(colors='#888', labelsize=6)

        # ── Panel 3/4: 3D voxel + skeleton + iso-surface ─────────────────────
        self.ax3d.cla()
        self.ax3d.set_facecolor('#080808')
        self.ax3d.set_xlim(0, VOXEL_RES); self.ax3d.set_ylim(0, VOXEL_RES)
        self.ax3d.set_zlim(0, VOXEL_RES)
        self.ax3d.set_title('3D Radio-Vision (Through-Wall Voxel Map)', fontsize=9, color='cyan')
        vg = self.voxel_grid
        vg_max = float(vg.max())
        # Skeleton always visible for spatial reference
        cx, cy, cz = VOXEL_RES // 2, VOXEL_RES // 2, VOXEL_RES // 2
        skel_head  = [(cx, cy, cz+10), (cx, cy, cz+6)]
        skel_torso = [(cx-5, cy, cz+4), (cx+5, cy, cz+4), (cx-8, cy, cz+1), (cx+8, cy, cz+1),
                      (cx-9, cy, cz-2), (cx+9, cy, cz-2), (cx, cy, cz), (cx, cy, cz-3)]
        skel_legs  = [(cx-3, cy, cz-6), (cx+3, cy, cz-6), (cx-3, cy, cz-11), (cx+3, cy, cz-11),
                      (cx-2, cy, cz-13), (cx+2, cy, cz-13), (cx, cy, cz-15)]
        for pts, col, sz in [(skel_head, 'white', 40), (skel_torso, 'yellow', 28), (skel_legs, 'cyan', 22)]:
            self.ax3d.scatter([s[0] for s in pts], [s[1] for s in pts], [s[2] for s in pts],
                              c=col, s=sz, alpha=0.85, depthshade=False)
        if vg_max > 0.05:
            x3, y3, z3 = np.meshgrid(np.arange(VOXEL_RES), np.arange(VOXEL_RES), np.arange(VOXEL_RES))
            lo_thr = max(0.05, vg_max * 0.35)
            hi_thr = max(0.12, vg_max * 0.65)
            mask_lo = (vg > lo_thr) & (vg <= hi_thr)
            mask_hi = vg > hi_thr
            if mask_lo.any():
                self.ax3d.scatter(x3[mask_lo], y3[mask_lo], z3[mask_lo],
                                  c=vg[mask_lo], cmap='cool', s=4, alpha=0.22,
                                  vmin=lo_thr, vmax=vg_max)
            if mask_hi.any():
                self.ax3d.scatter(x3[mask_hi], y3[mask_hi], z3[mask_hi],
                                  c=vg[mask_hi], cmap='hot', s=14, alpha=0.82,
                                  vmin=hi_thr, vmax=vg_max)
            try:
                verts, _ = marching_cubes_surface(vg, iso=max(0.12, vg_max * 0.5))
                if verts is not None and len(verts) > 0:
                    vv = verts[::max(1, len(verts) // 600)]
                    self.ax3d.scatter(vv[:, 0], vv[:, 1], vv[:, 2], c='lime', s=3, alpha=0.18)
            except Exception:
                pass
            # Pass 24: connected-component person detection — draw a wireframe box +
            # range label around each detected blob so distinct people are clearly marked.
            try:
                blobs = detect_voxel_blobs(vg, rel_thresh=0.45, max_blobs=4)
                self._detected_blobs = blobs
                box_colors = ['#ff3355', '#33ddff', '#ffdd33', '#aa66ff']
                for bi, blob in enumerate(blobs):
                    cx, cy, cz = blob["centroid"]
                    ex, ey, ez = blob["extent"]
                    col = box_colors[bi % len(box_colors)]
                    # Half-extents (clamped so the box is visible)
                    hx, hy, hz = max(ex / 2, 2), max(ey / 2, 2), max(ez / 2, 3)
                    x0, x1 = cx - hx, cx + hx
                    y0, y1 = cy - hy, cy + hy
                    z0, z1 = cz - hz, cz + hz
                    # 12 edges of the bounding cuboid
                    corners = [(x0, y0, z0), (x1, y0, z0), (x1, y1, z0), (x0, y1, z0),
                               (x0, y0, z1), (x1, y0, z1), (x1, y1, z1), (x0, y1, z1)]
                    edges = [(0, 1), (1, 2), (2, 3), (3, 0), (4, 5), (5, 6), (6, 7),
                             (7, 4), (0, 4), (1, 5), (2, 6), (3, 7)]
                    for a, b in edges:
                        xa, ya, za = corners[a]; xb, yb, zb = corners[b]
                        self.ax3d.plot([xa, xb], [ya, yb], [za, zb],
                                       color=col, lw=0.9, alpha=0.75)
                    # Range label above the blob
                    self.ax3d.text(cx, cy, z1 + 1.5,
                                   f"P{bi+1}  {blob['range_m']:.1f}m",
                                   color=col, fontsize=7, ha='center', weight='bold')
            except Exception as _be:
                log.debug(f"[3D] blob overlay skip: {_be}")
                self._detected_blobs = []
        _sim_val = getattr(self, "sim_validate", False)
        if _sim_val:
            # sim-validate test mode: ground-truth ✚ markers for accuracy comparison.
            try:
                for gt in p.get("ground_truth", []):
                    gx, gy, gz = gt["vox"]
                    self.ax3d.scatter([gx], [gy], [gz], marker='P', s=90,
                                      c='#00ff66', edgecolors='white', linewidths=0.6,
                                      alpha=0.95, depthshade=False)
                    self.ax3d.text(gx, gy, gz - 2.0, f"GT:{gt['id']}",
                                   color='#00ff66', fontsize=6, ha='center')
            except Exception:
                pass
        else:
            # Pass 26: REAL-DATA mode — plot every genuinely-measured node (router / LAN
            # host / AP) at its RSSI-derived range. Colour by kind; label id + range.
            _kind_col = {"router": "#ff3355", "lan_host": "#33ddff", "ap": "#ffdd33", "csi_echo": "#ff66ff"}
            try:
                for nd in p.get("real_nodes", []):
                    nx, ny, nz = nd["vox"]
                    col = _kind_col.get(nd["kind"], "#dddddd")
                    self.ax3d.scatter([nx], [ny], [nz], marker='o', s=70, c=col,
                                      edgecolors='white', linewidths=0.5,
                                      alpha=0.95, depthshade=False)
                    self.ax3d.text(nx, ny, nz - 1.6,
                                   f"{nd['id']}\n{nd['rssi']:.0f}dBm/{nd['range_m']:.1f}m",
                                   color=col, fontsize=5, ha='center')
            except Exception:
                pass
        self.ax3d.tick_params(labelsize=6, colors='#888')
        # Pass 26: apply navigable camera (WASD/arrows) + optional auto-rotation
        if getattr(self, "_rotate_mode", False):
            self._azim = (getattr(self, "_azim", -60.0) + 1.5) % 360
        self.ax3d.view_init(elev=getattr(self, "_elev", 22.0),
                            azim=getattr(self, "_azim", -60.0))
        if _sim_val:
            n_blobs = len(getattr(self, "_detected_blobs", []))
            num_persons = max(int(p.get("num_persons", 1)), n_blobs)
            pranges = p.get("person_ranges", [p.get("distance_m", 0.0)])
            range_str = ", ".join(f"{r:.1f}m" for r in pranges[:4]) if pranges else f"{p.get('distance_m',0):.1f}m"
            _acc = float(p.get("recon_accuracy", 0.0))
            _locked = p.get("recon_locked", False)
            _acc_tag = f"ACC {_acc:.1f}%" + (" ✓VALID" if _locked else "")
            _tcol = '#00ff66' if (_locked or _acc >= 95) else ('#ffcc33' if _acc >= 70 else '#ff5555')
            self.ax3d.set_title(f'3D Radio-Vision [SIM-VALIDATE] — {num_persons}P @ [{range_str}]   {_acc_tag}',
                                fontsize=8, color=_tcol)
        else:
            # Pass 26: real-data title — live capture method + node counts + signal health
            _method = p.get("capture_method", "?")
            _nn = p.get("real_node_count", 0)
            _rssi = p.get("live_rssi_dbm", -70.0)
            _real = p.get("real_capture", False)
            _src = "LIVE" if _real else "RSSI-synth (no CSI hw)"
            _tcol = '#00ffcc' if _real else '#ffaa44'
            self.ax3d.set_title(
                f'3D Radio-Vision [REAL · {_src}] — {_nn} nodes · {_method} · {_rssi:.0f} dBm',
                fontsize=8, color=_tcol)

        # ── Panel 5: Subcarrier activity heatmap + live snapshot line ─────────
        self.ax_heatmap.cla()
        self.ax_heatmap.set_facecolor('#080808')
        act = self.subcarrier_activity.astype(np.float32)
        act_max = float(act.max()) + 1e-6
        act_norm = act / act_max
        bar_colors = plt.cm.plasma(act_norm)
        self.ax_heatmap.bar(range(len(act)), act, color=bar_colors, width=1.0)
        if amp_hist.shape[0] > 0:
            snap = amp_hist[-1]
            snap_scaled = snap / (float(snap.max()) + 1e-6) * act_max
            self.ax_heatmap.plot(range(len(snap)), snap_scaled, color='cyan', lw=0.8, alpha=0.7)
        self.ax_heatmap.set_title('Subcarrier Activity + Live Amplitude Snapshot', fontsize=9, color='cyan')
        self.ax_heatmap.set_xlim(0, len(act))
        self.ax_heatmap.tick_params(colors='#888', labelsize=6)

        # ── Panel 6: Vitals trend ─────────────────────────────────────────────
        self.ax_vitals.cla()
        self.ax_vitals.set_facecolor('#080808')
        if len(self.vitals_history) > 2:
            vh = list(self.vitals_history)
            hrs = [v['hr'] for v in vh]
            brs = [v['br'] for v in vh]
            hrv = [v.get('hrv', 0) for v in vh]
            x_ax = range(len(hrs))
            self.ax_vitals.plot(x_ax, hrs, color='#ff4444', lw=1.2, label=f"HR {hrs[-1]:.0f}bpm")
            self.ax_vitals.plot(x_ax, brs, color='#44aaff', lw=1.2, label=f"BR {brs[-1]:.0f}/min")
            ax_hrv = self.ax_vitals.twinx()
            ax_hrv.plot(x_ax, hrv, color='#44ff88', lw=0.9, alpha=0.65, label='HRV')
            ax_hrv.set_ylabel('HRV ms', fontsize=7, color='#44ff88')
            ax_hrv.tick_params(colors='#888', labelsize=6)
            ax_hrv.set_facecolor('#080808')
            self.ax_vitals.legend(fontsize=7, loc='upper left', facecolor='#111', labelcolor='white')
            self.ax_vitals.set_ylim(0, max(max(hrs) * 1.2, 80))
            # Pass 23: horizontal reference lines — HR 60-100 bpm, BR 12-20 /min
            self.ax_vitals.axhline(60,  color='#ff4444', lw=0.6, ls='--', alpha=0.40)
            self.ax_vitals.axhline(100, color='#ff4444', lw=0.6, ls='--', alpha=0.40)
            self.ax_vitals.axhline(12,  color='#44aaff', lw=0.6, ls=':',  alpha=0.40)
            self.ax_vitals.axhline(20,  color='#44aaff', lw=0.6, ls=':',  alpha=0.40)
            # Gait annotation on vitals panel
            if p.get("surv_gait_active", False):
                self.ax_vitals.text(0.98, 0.92,
                    f"Gait {p.get('surv_gait_hz',0):.2f}Hz  Sym {p.get('surv_gait_symmetry',0):.2f}",
                    ha='right', va='top', transform=self.ax_vitals.transAxes,
                    color='#ffff44', fontsize=7)
        else:
            self.ax_vitals.text(0.5, 0.5, 'Calibrating vitals…', ha='center', va='center',
                                 color='cyan', transform=self.ax_vitals.transAxes, fontsize=9)
        self.ax_vitals.set_title('Live Vitals (HR / Breathing / HRV)', fontsize=9, color='cyan')
        self.ax_vitals.set_ylabel('bpm', fontsize=7, color='#aaa')
        self.ax_vitals.tick_params(colors='#888', labelsize=6)

        # ── Panel 9: BCI dashboard gauges ─────────────────────────────────────
        self.ax_bci.cla()
        self.ax_bci.set_facecolor('#080808')
        self.ax_bci.axis('off')
        gauges = [('Focus',   p.get('bci_focus', 0.0),       p.get('bci_focus_ci', 0.0)),
                  ('Stress',  p.get('bci_stress', 0.0),      p.get('bci_stress_ci', 0.0)),
                  ('Arousal', p.get('arousal_level', 0.0),   p.get('arousal_ci', 0.0)),
                  ('Threat',  p.get('threat_level', 0.0),    0.0),
                  ('β-ERD',   p.get('beta_suppression', 0.0), 0.0),
                  ('PAC',     p.get('pac_theta_gamma', 0.0),  0.0),
                  ('IHC',     p.get('ns_ihc', 0.0),           0.0)]   # Pass 23: 7th gauge — inter-hemispheric coherence
        n_g = len(gauges)
        bar_h = 0.10
        gap = 0.04
        total_h = n_g * (bar_h + gap)
        for i, (name, val, ci) in enumerate(gauges):
            yb = 0.95 - (i + 1) * (bar_h + gap)
            fill = float(np.clip(val, 0.0, 1.0))
            # background track
            self.ax_bci.add_patch(mpatches_rect(0.0, yb, 1.0, bar_h, '#1c1c1c',
                                                transform=self.ax_bci.transAxes))
            # filled bar
            self.ax_bci.add_patch(mpatches_rect(0.0, yb, fill, bar_h,
                                                plt.cm.RdYlGn_r(fill),
                                                transform=self.ax_bci.transAxes))
            self.ax_bci.text(-0.02, yb + bar_h * 0.35, name, fontsize=7.5, color='#dddddd',
                             ha='right', transform=self.ax_bci.transAxes)
            ci_str = f"±{ci:.2f}" if ci > 0.0 else ""
            self.ax_bci.text(1.02, yb + bar_h * 0.35, f"{val:.2f}{ci_str}",
                             fontsize=7, color='#cccccc', transform=self.ax_bci.transAxes)
        self.ax_bci.set_xlim(0.0, 1.0)
        self.ax_bci.set_ylim(0.0, 1.0)
        self.ax_bci.set_title(
            f"BCI — {p.get('bci_state', '?').upper()} | {p.get('ns_intent_label', '?')}",
            fontsize=8, color='cyan')

        # Panel 10-12: diagnostic overlay with confidence intervals (List 1.12)
        self.ax_diag.cla()
        self.ax_diag.set_facecolor('#080808')
        self.ax_diag.axis('off')
        cal = "✓ CALIBRATED" if self.calibrator.calibrated else f"CALIBRATING {self.calibrator.progress*100:.0f}%"
        adapt = "✓ADAPTED" if self.domain_adapted else "adapting"
        alert_line = ("  ⚠ ALERTS: " + ", ".join(p['anomaly_alerts'])) if p['anomaly_alerts'] else ""
        # Pass 19: pull new vitals fields for display
        _p_pnn50   = p.get('pnn50', 0.0)
        _p_pnn20   = p.get('pnn20', 0.0)
        _p_perf    = p.get('perfusion_index', 0.0)
        _p_pp      = p.get('pulse_pressure_proxy', 0.0)
        _p_sc      = p.get('skin_conductance_proxy', 0.0)
